sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float scale;
uniform float phase;
uniform float lineWidth;
layout(color) uniform half4 color1;
layout(color) uniform half4 color2;
layout(color) uniform half4 lineColor;
uniform float seed;
float hash12(float2 p) {
    float3 q = fract(float3(p.xyx) * 0.1031);
    q += dot(q, q.yzx + 33.33);
    return fract((q.x + q.y) * q.z);
}
float2 hash22(float2 p) {
    float3 q = fract(float3(p.xyx) * float3(0.1031, 0.1030, 0.0973));
    q += dot(q, q.yzx + 33.33);
    return fract((q.xx + q.yz) * q.zy);
}
float2 site(float2 n) {
    float2 h = hash22(n + seed * 19.19);
    float2 w = hash22(n + 71.3 + seed * 3.7);
    return 0.5 + 0.42 * float2(sin(6.2831853 * (phase * (0.5 + w.x) + h.x)), cos(6.2831853 * (phase * (0.5 + w.y) + h.y)));
}
half4 main(float2 coord) {
    half4 src = image.eval(coord);
    if (src.a <= 0.0) return src;
    float cell = size.y * max(scale, 0.01) / 13.0;
    float2 x = (coord - size * 0.5) / cell;
    float2 n = floor(x);
    float2 f = x - n;
    float2 best = float2(0.0);
    float2 bestCell = float2(0.0);
    float d1 = 8.0;
    for (int j = -1; j <= 1; j++) {
        for (int i = -1; i <= 1; i++) {
            float2 g = float2(float(i), float(j));
            float2 r = g + site(n + g) - f;
            float d = dot(r, r);
            if (d < d1) { d1 = d; best = r; bestCell = n + g; }
        }
    }
    float edge = 8.0;
    for (int j = -2; j <= 2; j++) {
        for (int i = -2; i <= 2; i++) {
            float2 g = float2(float(i), float(j));
            float2 r = g + site(n + g) - f;
            float2 diff = r - best;
            if (dot(diff, diff) > 0.00001) edge = min(edge, dot(0.5 * (best + r), normalize(diff)));
        }
    }
    float3 fill = mix(float3(color1.rgb), float3(color2.rgb), hash12(bestCell + seed * 5.3 + 0.37));
    float line = lineWidth > 0.0 ? 1.0 - smoothstep(lineWidth * 0.5 - 0.5 / cell, lineWidth * 0.5 + 0.5 / cell, edge) : 0.0;
    float3 rgb = mix(fill, float3(lineColor.rgb), line * float(lineColor.a));
    return half4(half3(rgb) * src.a, src.a);
}
